&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;L&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;earn, adjust, and stay effective through change&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Connection:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;C&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;ommunicat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, collaborat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, and build trust&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;To learn more about why these skills matter and what the data shows about thriving through change, read this &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot;&gt;blog post&lt;/a&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;from&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt; our Chief People Officer, Melanie Rosenwasser.&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-usually-unique-id=&quot;044234883370604133046166&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zqz90zkz74zz76zeez80zz68zz89zz88zvqz86zuxlz73zexxz80zz73z6d6z72zz79zsz77z&quot;&gt;Compensation&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Canada Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$191,300&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$258,700 CAD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2&gt;Role Description&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z9z90zz78zpz67zz74zz66zz85zy1z82zkz89zz89zt8z83zz65zz83z6z85zz78z8z77zz70zlz68zz81z7&quot;&gt;Security Engineers at Dropbox &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80ziz90zz66z78z76zz71zdz75zz89ztz80zlz90zz86zlisz88zz68zz88zoz83zz89zgz87zslz76zz80z&quot;&gt;safeguard our digital ecosystem alongside a diverse team of professionals dedicated to protecting our products and users. Trusted by millions, our mission is to integrate security seamlessly into Dropbox, empowering confident collaboration.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;thread-338994845393651446424878 author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z9z90zz78zpz67zz74zz66zz85zy1z82zkz89zz89zt8z83zz65zz83z6z85zz78z8z77zz70zlz68zz81z7&quot;&gt;In this role, you’ll build and operate the identity and access controls that help Dropbox employees, services, and AI agents access what they need securely. You’ll combine security engineering and automation to strengthen authentication and authorization, enforce least privilege, and simplify identity lifecycle management across our infrastructure. Working closely with Infrastructure, Corp Engineering, Developer Platform, and Incident Response, you’ll make secure access easier to use and maintain reliable IAM services as Dropbox adopts new AI tools and agentic workflows.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;Our Engineering Career Framework is &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://dropbox.github.io/dbx-career-framework/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://dropbox.github.io/dbx-career-framework/&quot;&gt;&lt;u&gt;viewable by anyone outside the company&lt;/u&gt;&lt;/a&gt;&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt; and describes what’s expected for our engineers at each of our career levels. Check out our blog post on this topic and more &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://dropbox.tech/culture/sharing-our-engineering-career-framework-with-the-world&quot; target=&quot;_blank&quot; data-target-href=&quot;https://dropbox.tech/culture/sharing-our-engineering-career-framework-with-the-world&quot;&gt;here&lt;/a&gt;&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;Responsibilities&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Design, deploy, and operate IAM controls across Dropbox’s cloud and on-premises infrastructure&lt;/li&gt;
&lt;li&gt;Design and implement secure identity, authentication, and authorization controls for AI agents and other non-human actors&lt;/li&gt;
&lt;li&gt;Implement least-privilege access using RBAC, ABAC, permission boundaries, service control policies, and just-in-time access&lt;/li&gt;
&lt;li&gt;Design secure integrations using SAML, OAuth 2.1, OpenID Connect, SCIM, and SPIFFE/SPIRE&lt;/li&gt;
&lt;li&gt;Automate identity lifecycle processes to ensure access is granted, modified, and revoked promptly&lt;/li&gt;
&lt;li&gt;Develop identity guardrails using infrastructure-as-code and policy-as-code&lt;/li&gt;
&lt;li&gt;Build monitoring and alerting for anomalous authentication, privilege escalation, credential misuse, and unauthorized access&lt;/li&gt;
&lt;li&gt;Partner with Incident Response to investigate identity-related incidents and rapidly revoke compromised access&lt;/li&gt;
&lt;li&gt;Conduct security reviews and threat modeling for new identity architectures and integrations&lt;/li&gt;
&lt;li&gt;Maintain IAM services with strong reliability, documentation, operational ownership, and on-call support&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot;thread-348589118974529206372994 attrcomment attrcommentfirst thread-348589118974529206372994-first author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84zyz72zz70zz71zz72zhwl8r6xz85zr3z69z6z86zz78zz76zcfvdsgm4t&quot;&gt;Many teams at Dropbox run Services with on-call rotations, which entails being available for calls during both core and non-core business hours. If a team has an on-call rotation, all engineers on the team are expected to participate in the rotation as part of their employment. Applicants are encouraged to ask for more details of the rotations to which the applicant is applying.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;Requirements&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z9z90zz78zpz67zz74zz66zz85zy1z82zkz89zz89zt8z83zz65zz83z6z85zz78z8z77zz70zlz68zz81z7&quot;&gt;5+ &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;years of security engineering experience, including substantial IAM or identity-security experience&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Hands-on experience with Okta, Okta for AI Agents and Sailpoint, or comparable technologies&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Strong understanding of authentication, authorization, least privilege, zero trust, and identity lifecycle management&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience with SAML, OAuth 2.0/2.1, OpenID Connect, SCIM, and MFA&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience designing RBAC or ABAC authorization models&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience securing human and non-human identities, including services, workloads, automation, and CI/CD systems&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience with agentic frameworks and MCP tool integration&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience implementing access reviews, privileged-access controls, and joiner/mover/leaver workflows&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Proficiency in at least one programming or scripting language, such as Python, Go, Java, Ruby, or Bash&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Experience with infrastructure-as-code, policy-as-code, APIs, and security automation&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qovukz87zz90zxpkuz122zz80zsz67zz122zm5fxz70zz77zfdz84zz70z4sgz89zcify&quot;&gt;Bachelor’s degree in Computer Science, Information Security, or a related field, or equivalent practical experience&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Preferred Qualifications&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Experience with workload identity technologies such as SPIFFE/SPIRE, Kubernetes service accounts, or cloud workload identity.&lt;/li&gt;
&lt;li&gt;Experience securing identities and authorization for AI agents and other autonomous systems.&lt;/li&gt;
&lt;li&gt;Experience with just-in-time access, zero-standing-privilege, or privileged-access management platforms.&lt;/li&gt;
&lt;li&gt;Familiarity with identity threat detection and response.&lt;/li&gt;
&lt;li&gt;Experience building IAM controls for multi-account cloud environments.&lt;/li&gt;
&lt;li&gt;Familiarity with NIST SP 800-63, NIST SP 800-207, CIS benchmarks, and relevant identity-security guidance.&lt;/li&gt;
&lt;li&gt;Experience supporting compliance programs such as SOC 2, ISO 27001, or FedRAMP.&lt;/li&gt;
&lt;li&gt;Security certifications such as CISSP, CCSP, or equivalent.&lt;/li&gt;
&lt;li&gt;Contributions to the identity or security community through open-source projects, publications, or conferences.&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;
&lt;h2&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z7z65z9wz73z7z75z6emz81zz70z4oz65zrz86z4dnz72ztz67zvoz67zl91&quot;&gt;Durable Skills&lt;/span&gt;&lt;/h2&gt;
&lt;/div&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;AI fluency means using these tools to &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;em&gt;amplify&lt;/em&gt;&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; human judgment, not replace it. We believe people with these skills will thrive as work and technology&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;continue to evolve:&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;listtype-bullet listindent1 list-bullet1&quot; data-testid=&quot;bullet-list&quot; data-test-indentation=&quot;1&quot;&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Awareness:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;U&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;nderstand &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;yourself&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; and others&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Judgment:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;E&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;valuat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt; information and mak&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;decisions in complex situations&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;L&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;earn, adjust, and stay effective through change&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Connection:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;C&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;ommunicat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, collaborat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, and build trust&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;To learn more about why these skills matter and what the data shows about thriving through change, read this &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot;&gt;blog post&lt;/a&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;from&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt; our Chief People Officer, Melanie Rosenwasser.&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-usually-unique-id=&quot;044234883370604133046166&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zqz90zkz74zz76zeez80zz68zz89zz88zvqz86zuxlz73zexxz80zz73z6d6z72zz79zsz77z&quot;&gt;Compensation&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;US Zone 1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;This role is not available in Zone 1&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;US Zone 2&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$193,500&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$261,900 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;US Zone 3&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$172,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$232,800 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2&gt;Role Description&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z9z90zz78zpz67zz74zz66zz85zy1z82zkz89zz89zt8z83zz65zz83z6z85zz78z8z77zz70zlz68zz81z7&quot;&gt;Security Engineers at Dropbox &lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80ziz90zz66z78z76zz71zdz75zz89ztz80zlz90zz86zlisz88zz68zz88zoz83zz89zgz87zslz76zz80z&quot;&gt;safeguard our digital ecosystem alongside a diverse team of professionals dedicated to protecting our products and users. Trusted by millions, our mission is to integrate security seamlessly into Dropbox, empowering confident collaboration.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;thread-729656182226573119751484 author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zz86z9z90zz78zpz67zz74zz66zz85zy1z82zkz89zz89zt8z83zz65zz83z6z85zz78z8z77zz70zlz68zz81z7&quot;&gt;In this role, you’ll help shape how Dropbox secures AI systems and agentic workflows, building and operating the controls that protect the infrastructure, tools, and data they rely on. You’ll tackle challenges such as prompt injection, secure agent access, and MCP integrations, turning emerging risks into practical, reusable safeguards. Partnering across engineering and security, you’ll lead hands-on work that enables teams to adopt AI safely while protecting customer data.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;Our Engineering Career Framework is &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://dropbox.github.io/dbx-career-framework/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://dropbox.github.io/dbx-career-framework/&quot;&gt;&lt;u&gt;viewable by anyone outside the company&lt;/u&gt;&lt;/a&gt;&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt; and describes what’s expected for our engineers at each of our career levels. Check out our blog post on this topic and more &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://dropbox.tech/culture/sharing-our-engineering-career-framework-with-the-world&quot; target=&quot;_blank&quot; data-target-href=&quot;https://dropbox.tech/culture/sharing-our-engineering-career-framework-with-the-world&quot;&gt;here&lt;/a&gt;&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z95lz89zy6z71zz79zz84zz68zyz69zupz72zz79zcz69zz76zkz79zp1z66ztz67zxz71zz89zz86zz71z&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;Responsibilities&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz80ziz90zz66z78z76zz71zdz75zz89ztz80zlz90zz86zlisz88zz68zz88zoz83zz89zgz87zslz76zz80z&quot;&gt;Design, deploy and operate infrastructure-level security controls for Dropbox&#39;s AI and agentic infrastructure, including cloud infrastructure, Kubernetes and data stores.&lt;/span&gt;&lt;/li&gt;
